styles:
.at-burst { position:fixed; pointer-events:none; font-size:1.5rem; font-weight:bold; animation:atFloatUp 0.6s ease-out forwards; z-index:100; }
@keyframes atFloatUp { 0% { opacity:1; transform:translateY(0); } 100% { opacity:0; transform:translateY(-60px); } }
.at-time-warn { animation:atPulse 0.5s ease-in-out infinite; color:#e74c3c !important; }
@keyframes atPulse { 0%,100% { opacity:1; } 50% { opacity:0.4; } }
